NOVEL_BATCH = [
 # ===== 标题简介 =====
 {"cat":"标题简介","genre":"悬疑","instruction":"为扎纸匠申冤民俗悬疑起书名并写简介。",
  "output":"【书名】《扎纸匠：我扎的纸人活了》\n【备选】《纸人点睛》《别给纸人点睛》\n【简介】\n扎纸匠老篾扎了一辈子纸人，规矩是：纸人不点睛，点睛就活。\n这天他给一个横死的姑娘扎纸人陪葬，手一抖，点了睛。\n当晚，那纸人站在他床头，姑娘的脸纸的身：「师傅，谢谢你给我点睛。我死得冤，你帮我申冤。」\n老篾吓得魂飞魄散。他干这行四十年，头一回真把纸人扎活了。\n「害我的人，就在镇上，人人都当他是大善人。」纸人姑娘渗出墨泪。\n老篾攥紧墨笔。他知道，自己这一笔，点的不是睛，是一桩躲不掉的冤。"},
 {"cat":"标题简介","genre":"悬疑","instruction":"为出马仙民俗悬疑起书名并写简介。",
  "output":"【书名】《出马仙：我身上的仙家等了三十年》\n【备选】《胡三太爷上身》《半仙之体》\n【简介】\n东北出马仙，讲究仙家上身看事。小满跟奶奶学了十年，从没真上过身。\n这天奶奶病重，有人来求看事，小满硬着头皮接了。她刚点上香，浑身一颤，一个苍老声音从嘴里传出：「小娃娃，借你身子一用。」\n小满意识清醒却控制不了身体，她「看」见自己开口，说出了来人家藏得最深的事，分毫不差。\n「奶奶，刚才是谁上了我的身？」\n「是咱家保家仙胡三太爷。」奶奶叹气，「他等了你十年，就等你身子骨长成，好借你的身，了他一桩心愿——一桩咱家欠了三十年的债。」\n小满不知道，自己这一上身，上出的不只是仙家，还有她半仙之体的秘密。"},
 {"cat":"标题简介","genre":"仙侠","instruction":"为苗疆蛊女仙侠起书名并写简介。",
  "output":"【书名】《蛊女：我的本命蛊是蛊王》\n【备选】《金蚕蛊》《苗疆蛊王》\n【简介】\n苗疆蛊女阿朵养了一只本命蛊——金蚕蛊。蛊在人在，蛊亡人亡。\n这天她照例喂蛊，金蚕蛊却忽然咬了她一口。她养了十年的本命蛊，从不咬主。\n她低头，看见金蚕蛊身上缠着一缕黑气——是被人下了噬主蛊。有人要借她的本命蛊反噬她！\n阿朵顺着黑气查，发现下蛊的，是寨子里最和善的阿婆。\n「阿婆，你为什么……」\n阿婆笑得阴冷：「阿朵，你养的金蚕蛊是蛊王。我养了一辈子蛊都没养出蛊王。我借你的蛊王续命，有何不可？」\n阿朵攥紧拳。她这才明白，最信任的阿婆，觊觎她的本命蛊，已经十年了。"},
 {"cat":"标题简介","genre":"玄幻","instruction":"为采参人玄幻起书名并写简介。",
  "output":"【书名】《采参人：我救的参娃娃成了精》\n【备选】《参祖》《长白山采参》\n【简介】\n采参人小参小时候救过一株人参——没挖它，反而给它浇了水。\n十年后，那株人参成了精，化作参娃娃来报恩：「小参，你救过我，我帮你找到参祖。」\n参祖能起死回生，小参病重的娘就等这味药。可参祖在禁地，有守山神，去了九死一生。\n「值得吗？」参娃娃问，「为了你娘，你可能回不来。」\n小参想起娘咳血的样子，一咬牙：「值得。我娘等不了了。」\n他不知道，这一趟挖出的不只是参祖，还有他十年前那瓢水结下的善缘，以及长白山藏了千年的秘密。"},
 {"cat":"标题简介","genre":"玄幻","instruction":"为淘金客玄幻起书名并写简介。",
  "output":"【书名】《淘金客：我放归的金子成了精》\n【备选】《金精》《金沙江淘金》\n【简介】\n淘金客小金小时候淘到一块金子，没卖，反而放回了江里——他觉得那金子有灵。\n十年后，那金子成了精，化作金精来报恩：「小金，你放了我，我帮你找到金脉。」\n小金穷了一辈子，想给娃好日子。可金脉在龙口，有塌方和金煞，去了未必回得来。\n「值得吗？」金精问。\n小金想起家里漏雨的屋、饿得直哭的娃，一咬牙：「值得。我穷怕了。」\n他不知道，这一趟淘出的不只是金脉，还有他十年前那一放结下的善缘，以及金沙江底藏了百年的诅咒。"},
 {"cat":"标题简介","genre":"历史","instruction":"为茶马古道马帮历史起书名并写简介。",
  "output":"【书名】《马帮锅头：我押的棺材里是活人》\n【备选】《茶马诡镖》《赶马帮的信义》\n【简介】\n茶马古道上，马帮锅头老骡子接了趟诡镖——押一口黑漆棺材送到藏地。雇主说棺里是活佛舍利，不许开棺。\n走到半山，他听见棺里传来倒念的经文，还夹着女人的哭：「放我出去……我不是舍利……」\n老骡子心头一凛。棺里是活人？这趟镖押的不是舍利，是个人！\n开棺，违约，还惹杀身之祸；不开，就是帮凶，害死一条人命。\n老骡子赶了三十年马帮，靠的是信义。可这趟镖的信义，是建立在一条人命上的。\n他深吸一口气，把刀撬向了棺盖。"},
 {"cat":"标题简介","genre":"悬疑","instruction":"为义庄守夜人民俗悬疑起书名并写简介。",
  "output":"【书名】《义庄守夜人：夜里别应声》\n【备选】《借声勾魂》《守义庄四十年》\n【简介】\n义庄守夜人老庚守了一辈子停尸的义庄。规矩是：夜里不管听见什么，都别应声。\n这天夜里，他听见一具新停的尸体喊他名字：「老庚……应我一声……」\n老庚攥紧旱烟杆没应。他干这行四十年，知道那是借声——一应声，魂就被勾走了。\n可那声音越来越像他死去的儿子：「爹……我是小栓啊……你应我一声，我就不冷了……」\n老庚的手抖了。小栓是他唯一的儿子，三年前溺死的。他明知道是借声，可那声音太像了。\n他闭上眼，咬破舌尖：「我儿子已经死了。你拿他骗我，我不应。」"},
 {"cat":"标题简介","genre":"悬疑","instruction":"为皮影戏申冤民俗悬疑起书名并写简介。",
  "output":"【书名】《皮影戏：我演的皮影自己动了》\n【备选】《皮影申冤》《别演真人真事》\n【简介】\n皮影戏艺人老影演了一辈子皮影。规矩是：皮影不演真人真事，演了，戏里的人就遭殃。\n这天他被人请去演一出新戏，戏文是镇上一桩旧事——一个被冤死的媳妇。演到一半，幕布上的皮影忽然自己动了，演出了戏文里没有的情节：那媳妇是被丈夫和婆婆合谋害死的。\n老影手一抖，皮影掉在地上。台下看戏的人里，那丈夫和婆婆脸色骤变。\n他捡起皮影，发现背面刻着一行小字：「替我申冤。」\n老影这才明白，请他演戏的不是要娱乐，是要借他的皮影，让冤死的媳妇自己演出真相。"},
 {"cat":"标题简介","genre":"都市","instruction":"为锁匠心锁都市起书名并写简介。",
  "output":"【书名】《锁匠：我能开人心里的锁》\n【备选】《心锁》《开锁匠的秘密》\n【简介】\n锁匠老开开了一辈子锁。可他有个秘密——他能开的不只是门锁，还有心锁：人心里藏着的事，他一眼就能开出来。\n这天一个客人请他开保险柜。老开一搭眼脸色变了——那柜里藏着一桩命案的秘密。\n「这柜，我不开。」老开收起工具。\n客人急了：「师傅，价钱随你开……」\n「不是钱的事。」老开压低声音，「这柜里的东西沾着人命。我开了，就是帮凶。」\n客人忽然冷笑：「老开，你以为你能不开？你开了我这么多锁，你的秘密，我也知道。」\n老开攥紧工具。他这才明白，自己被人拿捏了。"},
 {"cat":"标题简介","genre":"都市","instruction":"为修表匠修时间都市起书名并写简介。",
  "output":"【书名】《修表匠：我能修回被偷的时间》\n【备选】《时间不能偷》《修时间的人》\n【简介】\n修表匠老时修了一辈子表。可他有个秘密——他能修的不只是表，还有时间：别人浪费的时间，他能修回来一点。\n这天一个客人拿来一块停了的怀表。老时一搭眼脸色变了——那怀表里藏着客人被偷走的时间。\n「这表，你被人偷了时间。」老时说，「有人借你的表，偷了你十年阳寿。」\n客人浑身一震：「我最近确实老得快……」\n老时攥紧工具。他干这行四十年，头一回遇到偷时间的邪术。他知道偷时间的是个懂时术的人，就藏在客人身边。\n他不知道，修时间不是白修的——修回别人的时间，要用自己的时间换。"},
 {"cat":"标题简介","genre":"都市","instruction":"为古籍修复师都市起书名并写简介。",
  "output":"【书名】《古籍修复师：我修出了师父的血字》\n【备选】《禁书》《修书申冤》\n【简介】\n古籍修复师小纸整理师父遗物时，发现一封遗书：「小纸，师父不是病死的，是被人害死的。害我的人藏在一本古籍里。你修到那本书，就知道了。」\n小纸手一抖。他干这行十年，头一回知道师父是被害死的。\n他顺着线索找到那本古籍，修到一半，书页里浮现一行血字，写着凶手的名字。\n小纸浑身发冷。那名字，是他最信任的师兄。\n「师兄……为什么……」\n他这才明白，师父让他修古籍，不是传承手艺，是让他亲手查出害死师父的凶手。而那个凶手，就在他身边，看着他长大。"},
 {"cat":"标题简介","genre":"都市","instruction":"为调香师记忆香都市起书名并写简介。",
  "output":"【书名】《调香师：我调的香能勾出记忆》\n【备选】《记忆香》《良心香》\n【简介】\n调香师老香调了一辈子香。可他有个秘密——他能调出记忆香：闻了，就能想起被遗忘的事。\n这天一个客人请他调一款香，说能让人想起最痛苦的事。老香一调，忽然闻见了一段不属于他的记忆——那客人杀过人。\n老香手一抖。他调的香，把客人藏得最深的记忆勾了出来。\n「师傅，你的香真好。」客人笑了，「好到把我藏了十年的事都勾出来了。」\n老香攥紧香瓶。他这才明白，客人请他调香不是要想起痛苦，是要确认自己藏的事有没有被人知道。而他的香，恰恰暴露了：他知道了。\n「师傅，」客人凑近，声音冷了，「知道太多的人，往往活不长。」"},
 {"cat":"标题简介","genre":"悬疑","instruction":"为摸骨先生民俗悬疑起书名并写简介。",
  "output":"【书名】《摸骨先生：我摸到了死人的骨》\n【备选】《死骨》《借尸还魂》\n【简介】\n摸骨先生老骨摸了一辈子骨。规矩是：摸骨不断死骨，摸了就沾死人的因果。\n这天一个客人请他摸骨。老骨一搭手脸色变了——那骨相是个死人的骨相，可眼前的人明明活着。\n「客官，你这骨……」\n客人笑了：「没错，我是死人。我借了别人的身子活着。我想请你摸摸，我这副借来的身子还能撑多久。」\n老骨攥紧手。他干这行四十年，头一回遇到借尸还魂的。\n「还能撑多久？」客人问。\n老骨摸了半晌声音发颤：「三日。三日后这身子就烂了。」\n客人笑得阴冷：「再借一副。比如……你的。」"},
 {"cat":"标题简介","genre":"悬疑","instruction":"为测字先生民俗悬疑起书名并写简介。",
  "output":"【书名】《测字先生：我测了个死字》\n【备选】《死字》《囚字局》\n【简介】\n测字先生老测测了一辈子字。规矩是：测字不测死字，测了就应死人的事。\n这天一个客人写了个「囚」字请他测。老测一拆脸色变了——囚字是人被困在框里，是个死局。\n「客官，你这字……」\n客人笑了：「没错，我被困住了。困在一个出不去的局里。我想请你测测怎么出去。」\n老测攥紧笔。他干这行四十年，头一回遇到死字。\n「怎么出去？」客人问。\n老测拆了半晌声音发颤：「囚字要出去，得把人换成木，成了困，再破框。可这意味着，你得先死一次。」\n客人笑得阴冷：「死一次？好。那就请你，陪我死一次。」"},
 {"cat":"标题简介","genre":"悬疑","instruction":"为圆梦人民俗悬疑起书名并写简介。",
  "output":"【书名】《圆梦人：我圆了个死梦》\n【备选】《死梦》《棺材梦》\n【简介】\n圆梦人老圆解了一辈子梦。规矩是：圆梦不圆死梦，圆了就应死人的事。\n这天一个客人说自己夜夜做同一个梦：梦见自己躺在棺材里。老圆一解脸色变了——那不是梦，是预兆，客人三日内会死。\n「客官，你这梦……」\n客人笑了：「没错，我要死了。我想请你圆圆，我能不能不死。」\n老圆攥紧手。他干这行四十年，头一回遇到死梦。\n「能不能不死？」客人问。\n老圆解了半晌声音发颤：「能。但得有人替你死。」\n客人笑得阴冷：「你。圆梦人圆了死梦，就得替死。这是规矩。」"},
 {"cat":"标题简介","genre":"悬疑","instruction":"为走阴人民俗悬疑起书名并写简介。",
  "output":"【书名】《走阴人：我下阴间查案回不来了》\n【备选】《走阴》《阴阳勾结》\n【简介】\n走阴人老阴能下阴间问事。规矩是：走阴不带活人的东西，带了就被阴间留下。\n这天他受人之托下阴问命案。走到半路，发现怀里多了一枚活人的玉佩——是委托人偷偷塞的。\n老阴心头一凛。带了活人的东西，他被阴间标记了，回不去了。\n一个阴差走过来冷笑：「走阴人，你带了活人的东西，按规矩得留下。不过你要是帮我查清那桩命案，我就放你回去。」\n老阴攥紧玉佩。他这才明白，委托人塞玉佩不是害他，是逼他留在阴间，查清那桩阳间查不了的命案。"},
 {"cat":"标题简介","genre":"悬疑","instruction":"为问米婆民俗悬疑起书名并写简介。",
  "output":"【书名】《问米婆：我请错了魂》\n【备选】《问米申冤》《冤魂上身》\n【简介】\n问米婆阿婆能请死人的魂上身问话。规矩是：问米不问冤魂，问了就被冤魂缠上。\n这天一个客人请她问死去的丈夫。阿婆一请脸色变了——上来的不是她丈夫的魂，是个陌生的冤魂，开口就喊：「阿婆，替我申冤！」\n阿婆手一抖。她干这行五十年，头一回请错了魂。\n「你……你是谁？」\n「我是被人害死的。」冤魂借她的口说，「害我的人就在这个镇上，人人都当他是善人。阿婆，你帮帮我。」\n阿婆攥紧米碗。她这才明白，客人请她问丈夫是幌子，真正要她问的，是这桩没人敢查的冤。"},
 {"cat":"标题简介","genre":"玄幻","instruction":"为盐帮盐工玄幻起书名并写简介。",
  "output":"【书名】《盐工：我晒的盐里有毒》\n【备选】《毒盐》《晒盐的良心》\n【简介】\n盐帮盐工老盐晒了一辈子盐。这天他发现官仓的盐里掺了东西——不是沙，是能让人慢性中毒的毒盐。\n老盐心头一凛。他干这行三十年认得盐。这毒盐是有人故意掺的，要慢慢毒死吃盐的人。\n他顺着查，发现掺毒盐的是盐帮帮主，帮主背后是朝廷一个大官——他们要毒死某地百姓，好低价吞并那里的田。\n老盐浑身发冷。他一个盐工，知道了不该知道的秘密。说出去会死；可不说，那些百姓就慢慢被毒死。\n他攥紧那把毒盐。这一世，他要做那个把毒盐晒在阳光下的人。"},
 {"cat":"标题简介","genre":"历史","instruction":"为票号伙计历史起书名并写简介。",
  "output":"【书名】《票号伙计：我验出了假银票》\n【备选】《假银票》《验票的良心》\n【简介】\n票号伙计小票验了一辈子银票。这天他验出一张假银票——可那假票做得比真票还真，连暗记都分毫不差。\n小票心头一凛。他干这行十年，头一回遇到以假乱真到这份上的。能做出这种假票的，只有票号内部的人。\n他顺着查，发现做假票的是票号大掌柜。大掌柜做的假票已经流出去上百万两——一旦挤兑，整个票号就完了，无数存银的百姓血本无归。\n小票攥紧那张假票。他一个伙计，知道了不该知道的秘密。说出去会死；可不说，那些百姓就倾家荡产。\n他想起自己存银的老娘。这一世，他要做那个把假票戳穿的人。"},
 {"cat":"标题简介","genre":"历史","instruction":"为驿站驿卒历史起书名并写简介。",
  "output":"【书名】《驿卒：我送了一封催命信》\n【备选】《诡信》《送信的良心》\n【简介】\n驿站驿卒老驿送了一辈子信。这天他接到一封诡信——信封上没有收信人，只有一行字：「送信的，死。」\n老驿心头一凛。他干这行三十年，头一回遇到催命信。这信不是送给别人的，是送给他的。\n他拆开信，里面是一张名单——名单上的人都是当年参与过一桩冤案的官员，最后一个名字是他自己。\n老驿浑身发冷。他这才想起，三十年前他确实经手过一封信，那封信害死了一个忠臣。他以为只是送封信，原来他也是凶手之一。\n如今那忠臣的后人来复仇了。名单上的人已经死了大半，下一个是他。"},
 {"cat":"标题简介","genre":"历史","instruction":"为烽火台戍卒历史起书名并写简介。",
  "output":"【书名】《烽火台：我点错了烽火》\n【备选】《烽火》《守边关》\n【简介】\n烽火台戍卒老烽守了一辈子烽火台。规矩是：烽火不乱点，点了就是军情。\n这天他看见远处有敌情点了烽火。可烽火一点他才发现——那不是敌军，是友军。他点错了。\n老烽心头一凛。点错烽火是死罪。他干这行二十年，头一回犯这种错。\n可就在这时，他忽然发现那支友军打的是友军旗，穿的却是敌军甲——是敌军假扮的！他点的烽火没错！\n老烽猛地站起。他这才明白，有人故意让他以为点错了，好让他不敢再点烽火，放敌军入关。\n他攥紧火把。这一世，他要做那个把真正的烽火点起来的人。"},
 {"cat":"标题简介","genre":"玄幻","instruction":"为放排人玄幻起书名并写简介。",
  "output":"【书名】《放排人：夜里别放排》\n【备选】《水鬼拉排》《江上放排》\n【简介】\n放排人老排在江上放了一辈子木排。规矩是：夜里不放排，夜里放排，水鬼拉排。\n这天雇主急要他夜里放排，加了三倍钱。老排贪了钱夜里放了。走到江心，木排忽然不动了——像被什么东西在水下拉住。\n老排心头一凛。他干这行三十年，知道那是水鬼拉排——水鬼要替身，拉住排等排上的人下水。\n水面浮起一张脸，是他三年前溺死的徒弟：「师傅……下来陪我……」\n老排手一抖。他明知道是水鬼借了徒弟的脸，可那脸太像了。\n他闭上眼咬破舌尖：「我徒弟已经死了。你拿他骗我，我不下。」"},
 {"cat":"标题简介","genre":"悬疑","instruction":"为扶乩人民俗悬疑起书名并写简介。",
  "output":"【书名】《扶乩：乩笔自己写了冤》\n【备选】《扶乩申冤》《乩笔写凶》\n【简介】\n扶乩的老乩请了一辈子仙。规矩是：扶乩不问冤，问了冤魂就上身。\n这天有人请他扶乩问前程。乩笔一动，写出的不是前程，是一行血字：「替我申冤。」\n老乩手一抖。他干这行四十年，头一回请出了冤魂。\n「你……你是谁？」\n乩笔又动：「我是被人害死的。害我的人，就在今晚请乩的人里。」\n老乩浑身发冷。他抬头看向今晚请乩的几个人——他们个个面色如常，可其中有一个就是凶手。\n他这才明白，今晚的扶乩不是问前程，是有人要借他的手，让冤魂自己指出凶手。"},
 {"cat":"标题简介","genre":"玄幻","instruction":"为赶山人玄幻起书名并写简介。",
  "output":"【书名】《赶山人：我赶了绝户山》\n【备选】《山神讨命》《守山赎罪》\n【简介】\n赶山人老山在长白山赶了一辈子山。规矩是：赶山不赶绝户山，赶了山神讨命。\n这天他贪心赶了一座没人敢去的绝户山。刚进山就听见一个声音：「赶山的，你坏了规矩。这山的东西是留给我自己的。你拿了，得拿命换。」\n老山心头一凛。他干这行三十年，知道那是山神。他贪了心赶了绝户山，如今山神要讨命。\n「山神爷，我错了……」老山跪下。\n「错了？你采了我的参王，挖了我的药祖，打了我的守山兽。你拿什么赔？」\n老山攥紧手里的参。他咬牙：「我帮你守山。我用余生替你守这座山，赎我的贪。」"},
 {"cat":"标题简介","genre":"都市","instruction":"为文物修复师护宝都市起书名并写简介。",
  "output":"【书名】《文物修复师：我修出了文物的归乡愿》\n【备选】《文物回家》《修复师的尊严》\n【简介】\n文物修复师老修修了一辈子文物。这天他接到一件青铜器，修到一半发现内壁刻着一行诅咒：「修我者，三代不得好死。」\n老修手一抖。他干这行三十年，头一回遇到诅咒器。\n他低头，发现诅咒下面还有一行小字：「除非，你帮我回家。」\n老修这才明白，这器物里藏着一个流落异乡的魂。它不是要诅咒修它的人，是要找一个肯帮它回家的人。前面那些三代不得好死的，都是不肯帮它的。\n老修攥紧青铜器。他知道，自己修的不是器，是一桩流落了千年的归乡愿。而他，已经躲不掉了。"},
 # ===== 技法诊断改写 =====
 {"cat":"技法诊断改写","genre":"悬疑","instruction":"诊断这段民俗开篇的「迷信说教」问题并改写：『扎纸匠是封建迷信，我们要相信科学，不能搞这些。主角老篾是个扎纸匠，他认识到了迷信的危害，决定改行。』",
  "output":"【诊断】「迷信说教」——开篇就否定题材本身（说民俗是迷信要改行），既无冲突也无代入感，还自毁题材。民俗悬疑的魅力是「民俗里的真故事」，不是批判民俗。\n【改写】\n扎纸匠老篾扎了一辈子纸人，规矩是：纸人不点睛，点睛就活。\n这天他给一个横死的姑娘扎纸人陪葬，手一抖，点了睛。\n当晚，那纸人站在他床头：「师傅，谢谢你给我点睛。我死得冤，你帮我申冤。」\n【要点】民俗悬疑要「进入民俗的逻辑」，让民俗设定（点睛纸人活）成为故事引擎，而非开篇批判它。读者要的是「民俗里的悬疑」，不是「反迷信宣传」。"},
 {"cat":"技法诊断改写","genre":"悬疑","instruction":"诊断这段「异能无规则」问题并给改进：『主角什么民俗法术都会，请魂上身、走阴、摸骨、测字样样精通，没有任何限制，想用什么用什么。』",
  "output":"【诊断】「异能无规则」——主角样样精通无限制，民俗法术沦为万能工具，失去张力。民俗异能要「一门专精+严格规矩+代价」。\n【改进方向】\n①一门专精：主角只会一门（如扎纸/问米），不样样精通。\n②严格规矩：每门法术有禁忌（纸人不点睛/问米不问冤/走阴不带活物），破规矩有代价。\n③代价：用异能沾因果/损阳寿/被标记，不是白用。\n④异能有限：只能做特定的事，不能万能。\n【要点】民俗异能的魅力在「规矩与代价」。守规矩、付代价，异能才有重量；无规则的万能，只是开挂。"},
 {"cat":"技法诊断改写","genre":"悬疑","instruction":"诊断这段「冤魂直接给答案」问题并改进：『冤魂上身，直接把凶手是谁、尸首在哪、怎么害的全说了，主角照着抓人就行。』",
  "output":"【诊断】「冤魂直接给答案」——冤魂把一切都说清，主角照抓就行，没有推理过程，悬疑感尽失。冤魂线索要「碎片化+需验证+会误导」。\n【改进方向】\n①碎片化：冤魂只给片段（藏尸地/一个细节），不给完整答案。\n②需验证：冤魂说的不能直接定罪，主角得找实证（尸首/物证）。\n③会误导：冤魂带主观情绪，可能记错/有误会，主角得甄别。\n④官府不信：冤魂显灵官府不信，主角必须把超自然线索变成铁证。\n【要点】悬疑的爽感来自「把线索拼成真相」的过程。冤魂给答案，就剥夺了推理的乐趣。"},
 {"cat":"技法诊断改写","genre":"玄幻","instruction":"诊断这段「精怪无性格」问题并改进：『主角的精怪就是个工具，要它帮忙就帮忙，要它战斗就战斗，没有自己的想法。』",
  "output":"【诊断】「精怪无性格」——精怪沦为工具，没有自己的动机性格，读者记不住。精怪要「有自身目的+性格+与主角的羁绊」。\n【改进方向】\n①自身目的：精怪帮主角有自己的原因（报恩/了心愿/续命），不是无偿工具。\n②性格：精怪有脾气（傲娇/记仇/护短），不是听话的傀儡。\n③羁绊：精怪与主角是相互守护的伙伴，不是主仆。\n④成长：精怪也有自己的成长线（修行/了因果）。\n【要点】好精怪是「活物」不是「工具」。参娃娃报恩、金精守江，都有自己的故事，读者才记得住。"},
 {"cat":"技法诊断改写","genre":"历史","instruction":"诊断这段「古人皆蠢」问题并改进：『主角一个现代道理，古人们纷纷拜服，坏人都被主角轻松扳倒，毫无阻力。』",
  "output":"【诊断】「古人皆蠢+无阻力」——古人纷纷拜服、坏人轻松扳倒，忽略古代权力逻辑，失真。历史文要「古人有智慧+权力有阻力」。\n【改进方向】\n①古人有智慧：古人有自己的认知和利益考量，会质疑反驳，不会一听就拜服。\n②权力有阻力：扳倒坏人靠证据+渠道+博弈，不是「一说就灵」；坏人背后有势力，会反扑。\n③渐进：改变是渐进的，有妥协有代价。\n④主角有局限：主角懂专业但不懂权谋，会碰壁。\n【要点】尊重古人的智慧和历史的复杂，主角的逆袭才可信。轻松扳倒的坏人，衬不出主角的本事。"},
 {"cat":"技法诊断改写","genre":"都市","instruction":"诊断这段「手艺人悬浮」问题并改进：『主角一个手艺人，突然有了异能，立刻成为人上人，所有欺负他的人都跪了。』",
  "output":"【诊断】「手艺人悬浮」——突然有异能立刻人上人、所有人跪了，夸张失真。手艺人逆袭要「有积累+有过程+真实细节」。\n【改进方向】\n①异能有来源：异能是手艺练到极致的「升华」，或有传承缘由，不是天降。\n②逆袭有过程：不是一有异能就无敌，而是逐步用异能立足，有阻力。\n③反应真实：不是所有人跪了，而是有人震惊、有人不信、有人忌惮。\n④保留手艺人的本色：主角仍是手艺人，靠手艺+异能守公道，不是脱离手艺变人上人。\n【要点】手艺人的魅力是「手艺+匠心」。异能是手艺的延伸，不是脱离手艺的开挂。"},
 {"cat":"技法诊断改写","genre":"悬疑","instruction":"诊断这段「规矩无代价」问题并改进：『主角破了民俗规矩，没有任何后果，规矩就是说说而已。』",
  "output":"【诊断】「规矩无代价」——破规矩无后果，规矩沦为空话，失去张力。民俗规矩要「破则有代价」。\n【改进方向】\n①破规矩有代价：点睛纸人活/问冤沾因果/走阴带活物被标记，破规矩就有真实后果。\n②代价推动剧情：代价不是摆设，而是引发后续危机（被邪修盯上/沾因果）。\n③守规矩有智慧：主角守规矩不是迂腐，是懂规矩背后的道理。\n④破规矩是抉择：主角破规矩往往是「两害相权」的艰难抉择，不是随意。\n【要点】民俗规矩的张力在「代价」。破规矩有后果，规矩才有重量，主角的抉择才有分量。"},
 {"cat":"技法诊断改写","genre":"仙侠","instruction":"诊断这段「蛊术万能」问题并改进：『主角的蛊什么都能做，治病、杀人、控制人、飞行，无所不能。』",
  "output":"【诊断】「蛊术万能」——蛊无所不能，失去特色与张力。蛊术要「专精+限制+共生」。\n【改进方向】\n①专精：本命蛊有特定能力（如金蚕蛊是蛊王，主解毒/续命），不是万能。\n②限制：蛊在人在蛊亡人亡，蛊被动手脚会反噬，养蛊需正心。\n③共生：蛊与主角是共生关系，不是工具；心邪蛊就邪。\n④代价：用蛊耗心血，养蛊需付出。\n【要点】蛊术的魅力在「共生与正邪」。蛊不是万能工具，是与主角命运相连的伙伴，心正蛊正，心邪蛊邪。"},
 {"cat":"技法诊断改写","genre":"悬疑","instruction":"诊断这段「单元案件重复」问题并改进：『每个冤案都是冤魂上身说凶手，主角抓人，套路完全一样。』",
  "output":"【诊断】「单元案件重复」——每个冤案同一套路（冤魂说凶手→抓人），读者审美疲劳。单元案件要「诡计多样化+申冤方式差异化」。\n【改进方向】\n①诡计多样：不同冤案有不同死法/不同诡计（密室/伪装自杀/借刀杀人），不重复。\n②申冤方式多样：有的靠冤魂线索，有的靠物证推理，有的靠民俗法术，方式交替。\n③难度递进：冤案越来越复杂，凶手越来越狡猾。\n④主线串联：单元案件埋主线伏笔，逐步收束到大头目。\n【要点】单元案件的魅力在「新鲜感」。诡计和申冤方式多样化，读者才有持续追的动力。"},
 {"cat":"技法诊断改写","genre":"玄幻","instruction":"诊断这段「善缘无铺垫」问题并改进：『主角随便救了个精怪，精怪就来报恩给主角一切，没有任何铺垫。』",
  "output":"【诊断】「善缘无铺垫」——随便救个精怪就得一切报恩，善缘显得廉价。善缘要「有铺垫+有因果+有代价」。\n【改进方向】\n①善缘有铺垫：主角救精怪是出于本心（不贪/善良），不是刻意投资。\n②报恩有因果：精怪报恩有其原因（修行需善缘/了心愿），不是无偿。\n③报恩有代价：报恩也引来精怪的仇人，善缘伴随风险。\n④善缘是相互：主角也帮精怪（守山/守江），不是单向索取。\n【要点】善缘的魅力在「相互守护」。有铺垫的善缘是命运的回响，无铺垫的报恩是作者的施舍。"},
 {"cat":"技法诊断改写","genre":"都市","instruction":"诊断这段「异能解决一切」问题并改进：『主角有了异能，所有问题都靠异能解决，不用动脑不用努力。』",
  "output":"【诊断】「异能解决一切」——异能万能，主角不用动脑努力，失去张力。异能要「辅助+需智慧+有盲区」。\n【改进方向】\n①异能是辅助：异能给线索/工具，解决问题仍需主角智慧。\n②需动脑：异能给的线索要主角推理验证，不是直接给答案。\n③有盲区：异能有看不到的（如锁匠看物不看人），主角会因盲区吃亏。\n④有代价：用异能损身/沾因果，不是白用。\n【要点】异能是放大器，放大的是主角的智慧，不是替代智慧。靠异能躺赢，不如靠异能+动脑破局好看。"},
 {"cat":"技法诊断改写","genre":"历史","instruction":"诊断这段「专业无落地」问题并改进：『主角懂现代知识，随手就把古代难题解决了，没有任何落地过程。』",
  "output":"【诊断】「专业无落地」——现代知识随手解决古代难题，忽略落地的复杂，失真。专业要「有落地过程+时代局限」。\n【改进方向】\n①落地有过程：现代知识需原料、工艺、反复试验，不是随手就成。\n②时代局限：受生产力制约，主角得在局限内做事。\n③古人不蠢：古人会质疑、学习、利用，不是背景板。\n④专业是起点：专业知识是起点，落地靠主角的经营和博弈。\n【要点】历史文的代入感来自「真实的落地过程」。尊重时代局限，主角的专业才有说服力。"},
 {"cat":"技法诊断改写","genre":"悬疑","instruction":"诊断这段「反派降智」问题并改进：『害人的凶手都很蠢，留下明显破绽，主角一眼看穿。』",
  "output":"【诊断】「反派降智」——凶手蠢、留明显破绽，主角胜利廉价。凶手要「智商在线+百密一疏」。\n【改进方向】\n①凶手聪明：凶手布置周密，不是明显留破绽。\n②百密一疏：破绽是「算不到的意外变量」（天气/一个习惯），不是愚蠢。\n③主角靠推理：破绽靠主角细致观察+推理拼出，不是一眼看穿。\n④凶手会补救：凶手发现破绽会掩盖，与主角斗智。\n【要点】悬疑的爽感来自高手过招。凶手越强，主角破局越有含金量。降智的凶手配不上聪明的主角。"},
 {"cat":"技法诊断改写","genre":"玄幻","instruction":"诊断这段「守山无成长」问题并改进：『主角守山就是每天种参，没有任何成长和冲突，很无聊。』",
  "output":"【诊断】「守山无成长」——守山只是机械种参，无成长冲突，无聊。守山要「有成长+有冲突+有发现」。\n【改进方向】\n①守山有成长：主角从贪心到懂「取之有度」，心性成长。\n②守山有冲突：邪修来破封/觊觎灵脉，守山是战斗。\n③守山有发现：守的过程中发现山林秘密（山眼/封印），格局升级。\n④守山有羁绊：与山神/精怪的关系深化。\n【要点】守山不是机械劳动，是「赎罪+守护+发现」的成长线。有冲突有发现，守山才有看头。"},
 {"cat":"技法诊断改写","genre":"都市","instruction":"诊断这段「群像背景板」问题并改进：『手艺人联盟里，其他手艺人都是背景板，全靠主角一个人。』",
  "output":"【诊断】「群像背景板」——其他手艺人是背景板，全靠主角，失去群像魅力。群像要「各有价值+各有故事」。\n【改进方向】\n①各有绝活：每个手艺人异能不同（锁匠开心锁/修表修时间/调香勾记忆），不可替代。\n②各有故事：每个手艺人有自己的冤案/动机/成长，不是背景板。\n③协作制胜：破局靠各异能协作，不是主角一人。\n④主角是核心非全能：主角是串联者，但需要每个手艺人。\n【要点】群像的魅力是「一群人各显神通」。把每个手艺人写活，联盟才有温度，主角的领导力才显出来。"},
 {"cat":"技法诊断改写","genre":"悬疑","instruction":"诊断这段「民俗考据错误」问题并给建议：『作者把不同地域的民俗混在一起，东北出马仙和湘西赶尸混用，不伦不类。』",
  "output":"【诊断】「民俗考据错误」——不同地域民俗混用（东北出马仙+湘西赶尸），不伦不类，破坏真实感。民俗要「地域准确+考据扎实」。\n【建议】\n①地域准确：东北出马仙/湘西赶尸/苗疆蛊术，各有地域，不混用。\n②考据扎实：民俗规矩、术语、仪式要符合真实民俗，不瞎编。\n③聚焦一种：一部作品聚焦一种民俗体系，不贪多混用。\n④艺术加工有度：可以艺术加工，但不违背民俗的基本逻辑。\n【要点】民俗悬疑的真实感来自考据。地域准确、规矩扎实，读者才信；混用瞎编，就出戏了。"},
 {"cat":"技法诊断改写","genre":"仙侠","instruction":"诊断这段「正邪不分」问题并改进：『主角养的蛊和邪修的蛊没区别，都是害人，主角只是运气好。』",
  "output":"【诊断】「正邪不分」——主角的蛊与邪蛊无区别，主角只是运气好，失去价值内核。蛊术要「正邪有别+心正蛊正」。\n【改进方向】\n①正邪有别：正蛊救人共生，邪蛊害人驭人，本质不同。\n②心正蛊正：主角心正，蛊就正；邪修心邪，蛊就邪。蛊是心的镜子。\n③主角的选择：主角面临「用邪蛊走捷径」的诱惑，选择守正。\n④正邪对决：正蛊与邪蛊的对决，是价值观的对决。\n【要点】蛊术正邪之辨是价值内核。主角赢不是运气，是心正。心正蛊正，才有说服力。"},
 {"cat":"技法诊断改写","genre":"历史","instruction":"诊断这段「家国口号化」问题并改进：『主角天天喊爱国口号，但没有任何具体行动，家国情怀很空洞。』",
  "output":"【诊断】「家国口号化」——只喊口号无行动，家国情怀空洞。家国要「具体行动+真实代价」。\n【改进方向】\n①具体行动：家国情怀落在具体事上（守烽火/揭卖国/运良心粮），不是喊口号。\n②真实代价：为国要付出代价（被陷害/冒死/牺牲），不是空喊。\n③小人物视角：家国通过小人物的坚守体现，不是大人物的口号。\n④情感真实：家国是朴素的情感（护家乡/护百姓），不是空洞的口号。\n【要点】家国情怀的魅力在「具体的坚守」。一个戍卒守烽火、一个盐工晒毒盐，比喊一万句口号动人。"},
 {"cat":"技法诊断改写","genre":"都市","instruction":"诊断这段「传承无门槛」问题并改进：『主角的绝技随便教人，谁都能学，没有门槛。』",
  "output":"【诊断】「传承无门槛」——绝技随便教谁都能学，失去传承的庄重。传承要「有门槛+心正才传」。\n【改进方向】\n①心正才传：绝技传心正的人，心术不正学不到真本事。\n②传承有考验：学艺先学做人，通过考验才传绝技。\n③传承有重量：传承是责任，不是随便教。\n④正邪对比：心邪的邪徒学了皮毛就害人，衬托心正的重要。\n【要点】传承的魅力在「心正」。绝技传的是心正，不是手艺本身。有门槛的传承，才有庄重感。"},
 {"cat":"技法诊断改写","genre":"悬疑","instruction":"诊断这段「恐怖无逻辑」问题并改进：『鬼怪莫名其妙出现吓人，没有任何规则和逻辑，纯靠突然吓一跳。』",
  "output":"【诊断】「恐怖无逻辑」——鬼怪无规则纯吓人，靠突然惊吓，低级。民俗恐怖要「有规则+有因果+可理解」。\n【改进方向】\n①有规则：鬼怪遵循民俗规则（借声勾魂/拉替身/讨封），不是乱来。\n②有因果：鬼怪害人有原因（冤/怨/贪），不是无缘无故。\n③可理解：读者能理解鬼怪的逻辑，恐怖来自「规则下的必然」，不是突然。\n④可破：懂规则就能破，给主角和读者希望。\n【要点】高级的恐怖是「规则下的必然」。读者懂了规则，反而更怕——因为知道逃不掉。无规则的吓人，只是廉价惊吓。"},
 {"cat":"技法诊断改写","genre":"玄幻","instruction":"诊断这段「自然无敬畏」问题并改进：『主角向自然索取一切，山神金精都无条件给，没有任何敬畏和限度。』",
  "output":"【诊断】「自然无敬畏」——向自然无条件索取，失去「取之有度」的内核。自然题材要「敬畏+限度+共生」。\n【改进方向】\n①取之有度：向自然索取有限度，贪了有代价（山神讨命/金煞缠身）。\n②敬畏：主角对自然敬畏，不是征服。\n③共生：主角与自然共生（守山/守江），不是单向索取。\n④赎罪：贪了要赎（守山赎罪），不是白拿。\n【要点】自然题材的内核是「取之有度，共生共荣」。无条件索取是征服叙事，敬畏共生才是山林江河的魅力。"},
 {"cat":"技法诊断改写","genre":"都市","instruction":"诊断这段「良心无挣扎」问题并改进：『主角用良心香让坏人自首，坏人一闻就自首，没有任何挣扎。』",
  "output":"【诊断】「良心无挣扎」——坏人一闻香就自首，无挣扎，良心觉醒太容易。良心要「有挣扎+有过程」。\n【改进方向】\n①有挣扎：坏人良心被勾出后，会挣扎（否认/逃避/痛苦），不是立刻自首。\n②有过程：良心觉醒是渐进的，主角要引导，不是一蹴而就。\n③有代价：坏人自首要付出代价（坐牢/赎罪），不是轻松。\n④真实人性：坏人有复杂人性，不是非黑即白。\n【要点】良心觉醒的魅力在「挣扎」。坏人从否认到痛苦到自首的过程，才真实动人。一闻就自首，太廉价。"},
 {"cat":"技法诊断改写","genre":"悬疑","instruction":"诊断这段「主角无恐惧」问题并改进：『主角面对鬼怪邪祟毫无恐惧，像个战神，什么都不怕。』",
  "output":"【诊断】「主角无恐惧」——主角什么都不怕，像战神，失去真实感。民俗悬疑主角要「有恐惧+带着恐惧前行」。\n【改进方向】\n①有恐惧：主角会怕（怕鬼/怕死/怕沾因果），是普通人。\n②带着恐惧前行：主角怕，但为了申冤/守护，硬着头皮上，勇气更有分量。\n③恐惧真实：恐惧来自具体的威胁（被勾魂/被夺舍），不是空泛。\n④成长：主角从「怕得逃避」到「带着怕前行」，有成长。\n【要点】民俗悬疑的主角是「带着恐惧前行的普通人」。怕，却依然上，比什么都不怕的战神更动人。"},
 {"cat":"技法诊断改写","genre":"历史","instruction":"诊断这段「商帮无民俗」问题并改进：『写马帮漕帮盐帮，只有商业斗争，没有任何行当民俗和规矩。』",
  "output":"【诊断】「商帮无民俗」——只有商业斗争无行当民俗，失去商帮特色。商帮要「行当民俗+规矩+江湖气」。\n【改进方向】\n①行当民俗：马帮的诡镖规矩/盐帮的晒盐门道/票号的验票暗记，要具体。\n②规矩：商帮有行规（信义/取之有度），规矩是冲突来源。\n③江湖气：商帮有江湖义气、切口、仪式，不是纯商业。\n④民俗是引擎：行当民俗推动剧情（诡镖/毒盐/假票），不是背景。\n【要点】商帮的魅力在「行当民俗+江湖气」。具体的民俗规矩，让商帮有血有肉，不是抽象的商业斗争。"},
 {"cat":"技法诊断改写","genre":"悬疑","instruction":"诊断这段「申冤无温度」问题并改进：『主角申冤就是抓凶手，没有任何对死者的尊重和情感，冷冰冰。』",
  "output":"【诊断】「申冤无温度」——只抓凶手无情感，冷冰冰。申冤要「对死者的尊重+情感温度」。\n【改进方向】\n①尊重死者：主角申冤是为死者讨公道，不是完成任务；送死者安心离去。\n②情感温度：主角对死者有共情（理解冤/痛），不是冷冰冰。\n③仪式感：申冤后有「送魂」仪式（烧纸人/请魂走），有温度。\n④动机朴素：主角申冤出于朴素的良心，不是功利。\n【要点】申冤的魅力在「替说不出话的人说话」的温度。抓凶手是手段，给死者公道与尊严才是目的。有温度，申冤才动人。"},
 # ===== 人设 =====
 {"cat":"人设","genre":"悬疑","instruction":"为民俗悬疑设计一个扎纸匠主角人设。",
  "output":"【姓名】老篾\n【强标签】「扎了一辈子纸人的匠人，点睛扎活了冤魂」——纸人不点睛，他手一抖点了睛，扎出申冤的纸人。\n【反差感】表面是被人瞧不起的扎纸匠，实则身怀「点睛纸人活」的绝技。他的强是「手艺+良心」。\n【核心动机】最初是手艺，后来是「替冤魂申冤」——他扎的不是纸人，是公道。\n【性格底色】沉默、有匠心、重情。他守规矩（不点睛），可为了冤魂，宁可破规矩沾因果。\n【记忆点】他烧纸人送魂：「公道讨回来了，你安心走吧。」\n【成长线】从「被动扎纸」到「主动申冤」，最终明白手艺是守公道的本事。"},
 {"cat":"人设","genre":"悬疑","instruction":"为民俗悬疑设计一个出马仙弟子人设。",
  "output":"【姓名】小满\n【强标签】「半仙之体的出马弟子，胡三太爷等了十年」——身流一半仙家血，仙家借她上身看事。\n【反差感】表面是普通的出马弟子，实则是半仙之体。她的强是「仙家上身看穿隐秘」，但请神容易送神难。\n【核心动机】最初是替奶奶看事，后来是「了仙家因果+守公道」。\n【性格底色】善良、心正、有担当。她敬仙家，但不盲从；仙家有自身目的，她也警惕。\n【记忆点】胡三太爷说：「你这娃娃心正，我护你一辈子。」\n【成长线】从「被动上身」到「与仙家共生」，最终明白出马是人与仙的相互守护。"},
 {"cat":"人设","genre":"仙侠","instruction":"为仙侠设计一个苗疆蛊女人设。",
  "output":"【姓名】阿朵\n【强标签】「养蛊王的苗疆蛊女，心正蛊正」——本命蛊金蚕蛊是蛊王，被人觊觎。\n【反差感】表面是被阿婆害的蛊女，实则身怀蛊王、心正驭蛊。她的强是「心正蛊正」。\n【核心动机】最初是护本命蛊，后来是「守蛊术正道」——养蛊养的是心。\n【性格底色】坚韧、心正、有慈悲。她废了害她的阿婆的邪蛊，却救阿婆正心，不是滥杀。\n【记忆点】她说：「养蛊，养的是心。心正了，蛊就正了。」\n【成长线】从「护蛊」到「驭蛊王守正道」，最终明白蛊是共生伙伴不是工具。"},
 {"cat":"人设","genre":"玄幻","instruction":"为玄幻设计一个采参人人设。",
  "output":"【姓名】小参\n【强标签】「救过参精的采参人，不贪的善缘」——小时候救参精浇水，得参祖报恩救母。\n【反差感】表面是穷采参人，实则身怀「不贪」的善缘。他的强是「不贪+善缘」。\n【核心动机】最初是救母，后来是「守山报恩」——取之有度。\n【性格底色】孝顺、不贪、有匠心。他取参祖只取救母的量，不多取一分。\n【记忆点】他说：「采参，不是靠贪，是靠缘。你们采参是抢，我采参是缘。」\n【成长线】从「采参救母」到「守山护参共生」，最终明白山不是用来赶的，是用来守的。"},
 {"cat":"人设","genre":"玄幻","instruction":"为玄幻设计一个淘金客人设。",
  "output":"【姓名】小金\n【强标签】「放归金精的淘金客，不贪的善缘」——小时候放归金子，得金精报恩。\n【反差感】表面是穷淘金客，实则身怀「不贪」的善缘。他的强是「不贪+善缘」。\n【核心动机】最初是给娃好日子，后来是「守江报恩」——取之有度。\n【性格底色】爱家、不贪、有匠心。他取金脉只取够用的，不多取一分。\n【记忆点】他说：「淘金，不是靠贪，是靠缘。你们淘金是抢，我淘金是缘。」\n【成长线】从「淘金养家」到「守江护金共生」，最终明白金不是用来贪的，取之有度。"},
 {"cat":"人设","genre":"历史","instruction":"为历史设计一个马帮锅头人设。",
  "output":"【姓名】老骡子\n【强标签】「赶了三十年马帮的锅头，信义大于天」——押诡镖发现棺里是活人，宁可违约不做帮凶。\n【反差感】表面是赶马的粗人，实则信义大于天。他的强是「信义+良心」。\n【核心动机】守马帮的信义，但信义不能建立在人命上——良心是底线。\n【性格底色】重信义、有良心、有担当。他宁可违约得罪势力，也不做拐卖的帮凶。\n【记忆点】他说：「我赶马帮，赶的是信义，不是良心。良心没了，活着也没意思。」\n【成长线】从「守信义」到「守良心破拐卖」，最终明白信义的真谛是良心。"},
 {"cat":"人设","genre":"悬疑","instruction":"为民俗悬疑设计一个义庄守夜人人设。",
  "output":"【姓名】老庚\n【强标签】「守了四十年义庄的守夜人，夜里不应声」——守停尸义庄，识破借声勾魂。\n【反差感】表面是守死人的老头，实则身怀守夜正气。他的强是「正气+懂规矩」。\n【核心动机】守义庄守规矩，后来是「破借声勾魂守人心」。\n【性格底色】沉稳、守规矩、重情。他咬破舌尖不应「儿子」的借声，带着丧子之痛守正气。\n【记忆点】他说：「我儿子已经死了。你拿他骗我，我不应。」\n【成长线】从「守规矩不应声」到「主动破勾魂」，最终明白守的不是义庄，是正气。"},
 {"cat":"人设","genre":"都市","instruction":"为都市设计一个锁匠人设。",
  "output":"【姓名】老开\n【强标签】「开了一辈子锁的锁匠，能开心锁」——开锁还能开人心里的锁。\n【反差感】表面是普通锁匠，实则能看穿人心秘密。他的强是「开锁+防拿捏」。\n【核心动机】最初是开锁谋生，后来是「开锁申冤守公道」。\n【性格底色】沉稳、有匠心、懂留后手。他被人拿捏时，留了反制的后手。\n【记忆点】他说：「我开了一辈子锁，最懂的就是『留一手』。」\n【成长线】从「开锁谋生」到「开锁申冤」，最终明白开锁开的是公道。"},
 {"cat":"人设","genre":"都市","instruction":"为都市设计一个修表匠人设。",
  "output":"【姓名】老时\n【强标签】「修了一辈子表的修表匠，能修时间」——修表还能修回被偷的时间。\n【反差感】表面是普通修表匠，实则能修时间。他的强是「修时+正时」，但修时间损己阳寿。\n【核心动机】最初是修表谋生，后来是「修回被偷的时间守公道」。\n【性格底色】沉稳、有匠心、有牺牲精神。他明知修时间损己阳寿，仍替人修回。\n【记忆点】他说：「我修了一辈子表，最懂时间不能偷。你偷时间，时间就偷你的命。」\n【成长线】从「修表」到「修时间公道」，最终明白修的是时间公道，哪怕损己。"},
 {"cat":"人设","genre":"都市","instruction":"为都市设计一个古籍修复师人设。",
  "output":"【姓名】小纸\n【强标签】「修出师父血字的古籍修复师，心正传艺」——修古籍查出害师父的师兄。\n【反差感】表面是普通修复师，实则身怀「修出真相」的本事。他的强是「修复+心正」。\n【核心动机】最初是修书，后来是「修出真相申冤+传心正」。\n【性格底色】沉稳、心正、有匠心。他传艺先教心正，心邪的不教。\n【记忆点】他说：「师父传我绝技，不是偏心，是我心正。心邪了，学不到真本事。」\n【成长线】从「修书」到「修真相传心正」，最终明白修的是真相与心正。"},
 {"cat":"人设","genre":"都市","instruction":"为都市设计一个调香师人设。",
  "output":"【姓名】老香\n【强标签】「调了一辈子香的调香师，能勾良心」——调记忆香勾出凶手的良心让其自首。\n【反差感】表面是普通调香师，实则能勾记忆勾良心。他的强是「香术+良心」，但会被记忆反噬。\n【核心动机】最初是调香谋生，后来是「调良心助人」。\n【性格底色】沉稳、有匠心、有慈悲。他用良心香让坏人自首赎罪，也帮被愧疚困住的人。\n【记忆点】他说：「我调的不是香，是良心。良心安了，人就安了。」\n【成长线】从「调香」到「调良心」，最终明白调的是良心，也要赎自己的良心。"},
 {"cat":"人设","genre":"悬疑","instruction":"为民俗悬疑设计一个问米婆人设。",
  "output":"【姓名】阿婆\n【强标签】「问了一辈子米的问米婆，请冤魂申冤」——请魂上身替冤魂申冤，沾因果。\n【反差感】表面是普通问米婆，实则能请冤魂申冤。她的强是「请魂+申冤」，但问冤沾因果。\n【核心动机】最初是问米谋生，后来是「替冤魂申冤」。\n【性格底色】善良、有慈悲、有担当。她明知问冤沾因果，仍替冤魂申冤，渡人渡不了己。\n【记忆点】她说：「我问米，问的不是迷信，是公道。你害的人，自己来申冤了。」\n【成长线】从「问米」到「替冤魂申冤」，最终明白问的是公道，哪怕沾因果。"},
 {"cat":"人设","genre":"玄幻","instruction":"为玄幻设计一个赶山人人设。",
  "output":"【姓名】老山\n【强标签】「贪心赶绝户山的赶山人，守山赎罪」——贪心被山神讨命，选择守山赎罪。\n【反差感】表面是贪心的赶山人，实则知错能改守山赎罪。他的强是「守山+取之有度」。\n【核心动机】最初是贪心赶山，后来是「守山赎罪护山林」。\n【性格底色】知错能改、有担当、敬畏自然。他贪了认罚，用余生守山赎罪。\n【记忆点】他说：「我赶了一辈子山，如今才懂，山不是用来赶的，是用来守的。」\n【成长线】从「贪心赶山」到「守山赎罪共生」，最终明白取之有度补之有诚。"},
 # ===== 金手指系统 =====
 {"cat":"金手指系统","genre":"悬疑","instruction":"为民俗悬疑设计一个扎纸点睛金手指，要求有规矩代价。",
  "output":"【金手指】扎纸点睛\n【核心功能】扎的纸人点睛会活，能借纸人申冤。\n【规矩】①纸人不点睛，点睛就活；②点睛沾因果；③纸人申冤后要烧掉送魂。\n【限制/代价】①点睛的纸人会一直跟着主角（成了「孩子」）；②申冤沾因果缠身；③主角自己可能也是被扎的纸人（身世悬念）。\n【成长线】从「被动扎纸」到「主动申冤」，明白扎的是公道。\n【爽点来源】「纸人显灵申冤」的反差+「规矩代价」的张力。"},
 {"cat":"金手指系统","genre":"悬疑","instruction":"为民俗悬疑设计一个出马仙上身金手指。",
  "output":"【金手指】出马仙上身\n【核心功能】仙家借弟子上身看穿隐秘。\n【规矩】①请神容易送神难；②仙家有自身目的；③心正仙家才护。\n【限制/代价】①上身耗身；②仙家的因果要弟子了；③半仙之体引来邪修觊觎。\n【成长线】从「被动上身」到「与仙家共生」。\n【爽点来源】「仙家看穿隐秘」的爽+「请神送神」的张力。"},
 {"cat":"金手指系统","genre":"仙侠","instruction":"为仙侠设计一个本命蛊金手指，要求共生约束。",
  "output":"【金手指】本命蛊（金蚕蛊王）\n【核心功能】蛊王能解毒续命，是蛊术至宝。\n【共生约束】①蛊在人在蛊亡人亡；②蛊被动手脚会反噬；③心正蛊正心邪蛊邪。\n【限制/代价】①养蛊耗心血；②蛊王引来觊觎（邪蛊教）；③蛊王血能开蛊祖秘境（卷入阴谋）。\n【成长线】从「护蛊」到「驭蛊王守正道」。\n【爽点来源】「蛊王反制」的爽+「共生约束」的张力。"},
 {"cat":"金手指系统","genre":"玄幻","instruction":"为玄幻设计一个参精善缘金手指。",
  "output":"【金手指】参精善缘\n【核心功能】救过的参精报恩，带主角找参祖。\n【善缘机制】①善缘需本心（不贪）；②报恩有因果（参精有自身目的）；③善缘是相互（主角也守山护参）。\n【限制/代价】①参祖在禁地有守山神；②取参祖别贪，贪了陪守山神；③参祖气息引来参猎者。\n【成长线】从「采参救母」到「守山护参共生」。"},
 {"cat":"金手指系统","genre":"玄幻","instruction":"为玄幻设计一个金精善缘金手指。",
  "output":"【金手指】金精善缘\n【核心功能】放归的金精报恩，带主角找金脉。\n【善缘机制】①善缘需本心（不贪）；②报恩有因果；③善缘是相互（主角守江护金）。\n【限制/代价】①金脉在龙口有金煞；②取金脉别贪，贪了做守金人；③金精气息引来金猎者。\n【成长线】从「淘金养家」到「守江护金共生」。"},
 {"cat":"金手指系统","genre":"悬疑","instruction":"为民俗悬疑设计一个守夜正气金手指。",
  "output":"【金手指】守夜正气\n【核心功能】守义庄积累的守夜正气，能破借声勾魂。\n【规矩】①夜里不应声（防借声）；②正气需守规矩积累；③正气破邪。\n【限制/代价】①守夜人可能是被「守」成的活人（身世悬念）；②正气耗尽就散；③守的是自己的命。\n【成长线】从「守规矩」到「主动破勾魂」。\n【爽点来源】「正气破邪」的爽+「身世悬念」的张力。"},
 {"cat":"金手指系统","genre":"都市","instruction":"为都市设计一个心锁异能金手指。",
  "output":"【异能】心锁\n【核心功能】开锁还能开人心里的锁（看穿秘密）。\n【限制】①只能看物不能看人心算计；②看穿秘密也被别人拿捏；③需留后手防反制。\n【代价】看穿太多秘密沾因果，被秘密的主人盯上。\n【成长线】从「开锁谋生」到「开锁申冤」。\n【爽点来源】「看穿秘密」的爽+「互相拿捏」的张力。"},
 {"cat":"金手指系统","genre":"都市","instruction":"为都市设计一个修时间异能金手指。",
  "output":"【异能】修时间\n【核心功能】修表还能修回被偷的时间。\n【代价机制】①修回他人时间，自损阳寿；②修的时间越多，自己阳寿越少；③偷来的时间根基不稳，修回的物归原主。\n【限制】①只能修「被偷」的时间，不能凭空增寿；②修时间耗心神。\n【成长线】从「修表」到「修时间公道」，哪怕损己。\n【爽点来源】「修回时间」的爽+「损己阳寿」的代价。"},
 {"cat":"金手指系统","genre":"都市","instruction":"为都市设计一个修复真相异能金手指。",
  "output":"【异能】修复真相\n【核心功能】修古籍/文物能修出藏着的真相/归乡愿。\n【限制】①只能修出「藏着的」，不能凭空知道；②修出真相沾因果；③心正才修得出真本事。\n【代价】修出真相被真相的主人/凶手盯上。\n【成长线】从「修书」到「修真相申冤传心正」。\n【爽点来源】「修出真相」的爽+「心正传承」的温度。"},
 {"cat":"金手指系统","genre":"都市","instruction":"为都市设计一个记忆香异能金手指。",
  "output":"【异能】记忆香\n【核心功能】调香勾记忆/改记忆/勾良心。\n【限制】①勾记忆会被记忆反噬（别人的记忆住进脑子）；②勾良心也勾自己的良心；③香术需心正。\n【代价】勾太多人的记忆，分不清自己的和别人的；自己的良心也被勾出要赎。\n【成长线】从「调香」到「调良心助人赎己」。"},
 {"cat":"金手指系统","genre":"悬疑","instruction":"为民俗悬疑设计一个问米请魂金手指。",
  "output":"【金手指】问米请魂\n【核心功能】请死者魂上身申冤。\n【规矩】①问米不问冤，问冤沾因果；②冤魂上身申冤后要送魂；③请魂需心正。\n【限制/代价】①问冤沾因果缠身，渡人渡不了己；②冤魂带主观情绪会误导；③请魂耗身。\n【成长线】从「问米」到「替冤魂申冤」。\n【爽点来源】「冤魂申冤」的爽+「沾因果」的代价。"},
 {"cat":"金手指系统","genre":"悬疑","instruction":"为民俗悬疑设计一个走阴金手指。",
  "output":"【金手指】走阴\n【核心功能】下阴间问事查案。\n【规矩】①走阴不带活人的东西，带了被标记；②阴阳不相扰；③走阴需正气。\n【限制/代价】①带活物被阴间标记回不去；②破阴阳界限永远留阴间；③走阴耗阳寿。\n【成长线】从「走阴问事」到「破阴阳勾结守公道」。\n【爽点来源】「下阴查案」的新鲜+「回不去」的代价。"},
 {"cat":"金手指系统","genre":"玄幻","instruction":"为玄幻设计一个守山赎罪金手指。",
  "output":"【金手指】守山赎罪\n【核心功能】守山赎贪心之罪，得山神庇护，发现山林秘密。\n【机制】①取之有度，贪了讨命；②守山赎罪可免讨命；③守山发现山眼/封印秘密。\n【限制/代价】①守山比赶山苦；②山眼镇着上古存在，守山是守封印；③贪心反复会再被讨命。\n【成长线】从「贪心赶山」到「守山赎罪共生」。"},
 {"cat":"金手指系统","genre":"悬疑","instruction":"为民俗悬疑设计一个扶乩申冤金手指。",
  "output":"【金手指】扶乩申冤\n【核心功能】扶乩请冤魂上乩笔写出真相。\n【规矩】①扶乩不问冤，问冤沾因果；②冤魂写真相后要送魂；③扶乩需心正。\n【限制/代价】①问冤沾因果，渡人渡不了己；②乩笔写的需验证不能直接定罪；③扶乩耗身。\n【成长线】从「扶乩问前程」到「替冤魂申冤」。\n【爽点来源】「乩笔写凶」的爽+「沾因果」的代价。"},
]